package dev.pocketengine.phone.observation;

import dev.pocketengine.core.NativeToolPlan;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
import static dev.pocketengine.phone.observation.PhoneCollectionFixtures.*;

/** Explicit physical-tree fixtures exercise matching; no action backend or Android user is simulated here. */
public final class PhoneTreeSequenceTest {
    static JSONObject actual(String id)throws Exception {
        JSONObject o=tree(id,"Button","Input");o.put("observationBinding",j("taskId","t","runId","r","epoch",3,"displayId",5,"sessionId","s"));
        for(int i=0;i<o.getJSONArray("nodes").length();i++){JSONObject n=o.getJSONArray("nodes").getJSONObject(i);n.put("identityFingerprint",(100+i)+":"+String.valueOf((char)('a'+i)).repeat(64));}
        o.getJSONArray("nodes").getJSONObject(2).put("clickable",true);o.getJSONArray("nodes").getJSONObject(4).put("editable",true);return o;
    }
    static JSONObject target(int...path)throws Exception {JSONArray p=new JSONArray();for(int v:path)p.put(v);return j("windowId",9,"path",p);}
    static JSONObject click()throws Exception {return j("tool","phone_click_node","target",target(0,0));}
    static JSONObject type()throws Exception {return j("tool","phone_type","target",target(1,0),"text","literal user text");}
    static JSONObject proposal(JSONObject...steps)throws Exception {JSONArray out=new JSONArray();for(JSONObject step:steps)out.put(step);return j("observationId","o0","steps",out);}
    @Test public void freshIdsResolveSameNativeWindowPathAndNeverReturnAPlanLoop()throws Exception {PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(click(),type()),actual("o0"),100);s.start("o0");JSONObject fresh=actual("o1"),a=s.resolve(0,fresh,200);assertEquals("o1",a.getString("observationId"));assertEquals("n2",a.getString("nodeId"));assertEquals(2,a.length());assertEquals(NativeToolPlan.Tool.CLICK_NODE,s.tool(0));assertEquals("literal user text",s.resolve(1,actual("o2"),300).getString("text"));}
    @Test public void changedCompleteIdentityRejectsEvenWhenDisplayedSummaryIsUnchanged()throws Exception {PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(click(),type()),actual("o0"),100);JSONObject fresh=actual("o1");fresh.getJSONArray("nodes").getJSONObject(4).put("identityFingerprint","104:"+"f".repeat(64));assertThrows(SecurityException.class,()->s.resolve(1,fresh,200));}
    @Test public void unchangedButtonBesideClippedLongArticleRemainsVerifiable()throws Exception {JSONObject initial=actual("o0");initial.getJSONObject("treeCoverage").put("bodyTruncated",true);initial.getJSONArray("nodes").getJSONObject(3).put("text","article".repeat(60));PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(click()),initial,100);JSONObject next=new JSONObject(initial.toString()).put("observationId","o1");assertEquals("n2",s.resolve(0,next,200).getString("nodeId"));}
    @Test public void incompleteAndUnregisteredInitialTargetsAreNotGuessed()throws Exception {JSONObject incomplete=actual("o0").put("truncated",true);assertThrows(SecurityException.class,()->PhoneTreeSequence.prepare(proposal(click()),incomplete,100));assertThrows(SecurityException.class,()->PhoneTreeSequence.prepare(proposal(j("tool","phone_click_node","target",target(6))),actual("o0"),100));}
    @Test public void nativeIdentityCannotBeReplacedByTextOrAHashInventedFromTheShownSummary()throws Exception {JSONObject o=actual("o0");o.getJSONArray("nodes").getJSONObject(2).put("identityFingerprint","identity-n2");assertThrows(SecurityException.class,()->PhoneTreeSequence.prepare(proposal(click()),o,100));}
    @Test public void hiddenPasswordDisabledAndWrongActionCapabilityAreRejected()throws Exception {for(String flag:new String[]{"password","enabled","visible","clickable"}){JSONObject o=actual("o0");o.getJSONArray("nodes").getJSONObject(2).put(flag,flag.equals("password"));assertThrows(flag,SecurityException.class,()->PhoneTreeSequence.prepare(proposal(click()),o,100));}}
    @Test public void pauseSessionApplicationAndTimeChangesStopRemainingSteps()throws Exception {PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(click()),actual("o0"),100);for(String key:new String[]{"pauseRevision","packageName"}){JSONObject o=actual("o1");o.put(key,key.equals("pauseRevision")?1:"another.app");assertThrows(SecurityException.class,()->s.resolve(0,o,200));}JSONObject other=actual("o1");other.getJSONObject("observationBinding").put("sessionId","rebuilt");assertThrows(SecurityException.class,()->s.resolve(0,other,200));assertThrows(SecurityException.class,()->s.resolve(0,actual("late"),20101));}
    @Test public void initialLatestMustStillMatchAndSequenceCannotStartTwice()throws Exception {PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(click()),actual("o0"),100);assertThrows(SecurityException.class,()->s.start("changed"));s.start("o0");assertThrows(SecurityException.class,()->s.start("o0"));}
    @Test public void explicitFuturePredicateIsReadOnlyAndUsesTheRealFreshObservation()throws Exception {JSONObject wait=j("tool",PhoneTreeQuery.WAIT,"condition",j("kind","present","selector",j("text","future status"),"timeoutMs",6000));PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(wait),actual("o0"),100);JSONObject args=s.resolve(0,actual("o1"),200);assertEquals("o1",args.getString("observationId"));assertEquals("present",args.getString("kind"));assertEquals(NativeToolPlan.Tool.CONDITION_WAIT,s.tool(0));}
    @Test public void conditionWaitCannotRequestMoreThanTheRemainingSequenceWindowOrWeakenRequiredStability()throws Exception {JSONObject condition=j("kind","present","selector",j("text","future status"),"timeoutMs",6000),wait=j("tool",PhoneTreeQuery.WAIT,"condition",condition);PhoneTreeSequence.State state=PhoneTreeSequence.prepare(proposal(wait),actual("o0"),100);assertEquals(600,state.resolve(0,actual("o1"),19500).getInt("timeoutMs"));assertEquals(6000,condition.getInt("timeoutMs"));assertThrows(SecurityException.class,()->state.resolve(0,actual("o2"),20100));JSONObject stable=j("tool",PhoneTreeQuery.WAIT,"condition",j("kind","stable","selector",j("text","future status"),"timeoutMs",6000,"stableForMs",1000));PhoneTreeSequence.State required=PhoneTreeSequence.prepare(proposal(stable),actual("o0"),100);assertThrows(SecurityException.class,()->required.resolve(0,actual("o1"),19500));}
    @Test public void noCoordinatesNavigationOverallPermitOrEmptyUnboundedPlan()throws Exception {for(JSONObject invalid:new JSONObject[]{proposal(),proposal(click(),click(),click(),click(),click()),proposal(j("tool","phone_tap","x",4,"y",5)),proposal(click()).put("approvalId","model"),proposal(j("tool",PhoneTreeQuery.WAIT,"condition",j("kind","present","selector",j("parentId","n1"),"observationId","old","timeoutMs",1000)))})assertThrows(Exception.class,()->PhoneTreeSequence.validate(invalid));}
    @Test public void declaredIdentityAndLiteralTextAreStrictWithoutTurningIntoTargetQueries()throws Exception {JSONObject c=click();c.getJSONObject("target").put("resourceId","wrong");assertThrows(SecurityException.class,()->PhoneTreeSequence.prepare(proposal(c),actual("o0"),100));JSONObject t=type().put("text","");PhoneTreeSequence.State s=PhoneTreeSequence.prepare(proposal(t),actual("o0"),100);assertEquals("",s.resolve(0,actual("o1"),200).getString("text"));}
    @Test public void actualPluginRulesAcceptsOnlyTheSupportedSequenceSchemaSubset()throws Exception {dev.pocketengine.features.plugins.PluginRules.validateArguments(proposal(click(),type()),PhoneTreeSequence.schema());assertThrows(IllegalArgumentException.class,()->dev.pocketengine.features.plugins.PluginRules.validateArguments(proposal(click()).put("grant",true),PhoneTreeSequence.schema()));assertTrue(PhoneTreeQuery.supports(PhoneTreeSequence.TOOL));PhoneTreeQuery.validate(PhoneTreeSequence.TOOL,proposal(click()));}
}
